"""Render the measured arena/header-cache optimization and its MMAP ablation."""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
directory = ROOT / 'suite/reports'
p = json.loads((directory / 'c-preprocessor-arena-analysis-20261015.json').read_text())
style = (directory / 'c-frontend-profile-20261015.html').read_text().split('<style>', 1)[1].split('</style>', 1)[0]
data = {'applications': p['applications'], 'aggregate': p['aggregate']}
# The compact presentation only needs batch counters, not all individual files.
for row in data['applications'].values():
    for name in ['baseline', 'candidate']:
        row['storage'][name].pop('files', None)
        row['storage'][name].pop('command', None)
        row['storage'][name].pop('time_stderr', None)
    row['storage']['cache_stats'].pop('files', None)
    row['storage']['cache_stats'].pop('command', None)
html = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arena and header cache results</title><style>__STYLE__
.bargroup{margin:15px 0 22px}.bargroup b{display:block;margin-bottom:5px}.barline{display:grid;grid-template-columns:112px 1fr 68px;gap:7px;align-items:center;margin:5px 0;font-size:12px}.barline .track,.barline .segment{height:16px}.barline span:last-child{text-align:right;font-variant-numeric:tabular-nums}.finding p{margin:8px 0}.ok{color:var(--success,#42a57a)}@media(max-width:450px){.barline{grid-template-columns:95px 1fr 60px;gap:5px;font-size:11px}.stats{gap:6px}.stat strong{font-size:19px}}
</style></head><body>
<h2>Another <span id="increment"></span> from arenas and header caching</h2>
<p class="meta muted">Apple M5 Max · release + symbols · 11 paired rounds · 44 translation units · 15 Oct 2026</p>
<p class="lead">Token text now borrows source storage, macro definitions and hide sets use an arena, and each include’s source and lexical tokens are cached per translation unit. Large headers use memory maps.</p>
<div class="stats"><div class="stat"><strong id="overall"></strong><span>faster than the original preprocessor, measured in the same rounds</span></div><div class="stat"><strong>96% fewer</strong><span>allocation/reallocation calls versus the previous optimized version</span></div><div class="stat"><strong>64 pass</strong><span>frontend and driver tests; all 44 application outputs byte-identical</span></div></div>
<div class="controls"><button id="absolute" class="active" onclick="setRelative(false)">Milliseconds</button><button id="relative" onclick="setRelative(true)">Relative to previous</button></div>
<div class="legend"><span class="key" style="--c:#939aa7">Previous optimized</span><span class="key" style="--c:#4d9ed6">Arena, no source cache</span><span class="key" style="--c:#d9a24d">Arena + cached reads</span><span class="key" style="--c:#46aa93">Arena + cached maps</span></div><div id="bars" aria-label="Incremental preprocessing costs"></div>
<div class="tablewrap"><table><thead><tr><th>Application</th><th>Original ms</th><th>Previous ms</th><th>Final ms</th><th>New speedup</th><th>95% interval</th><th>Total speedup</th></tr></thead><tbody id="timing"></tbody></table></div>
<p class="note">Serial preprocessing batches. Times are medians; speedups use median same-round ratios, so dividing the displayed medians may differ. Every variant was built and frozen before timing; the original was remeasured in these same rounds.</p>
<h3>Where the gain comes from</h3>
<div class="finding"><p><strong>Arena-backed data and borrowed text:</strong> tokens are cheap copies of source spans. Macro nodes, parameter/body slices, generated text and persistent hide sets share a per-call bump arena. File owners retain mapped or read source buffers until preprocessing finishes.</p><p><strong>Bounded buffer lifetime:</strong> large token buffers have exact-size owners in a separate typed arena. This avoids retaining the obsolete capacities of growing vectors inside the bump arena. All owned sources, maps, tokens and macro storage are released when the call ends; the returned string owns its text.</p><p><strong>Header reuse:</strong> source text and lexical tokens are cached by canonical path, with disk and embedded files distinguished. Macro expansion still runs with current definitions on each include. Conservative complete-header guards can skip inactive bodies; <code>#undef</code>, <code>include_next</code>, aliases and <code>#line</code> retain their semantics.</p><p><strong>Direct output:</strong> line markers and escaped paths are written directly to the returned output buffer, avoiding temporary formatting strings.</p></div>
<h3>Read caching provides most of the file-access benefit</h3>
<div class="tablewrap"><table><thead><tr><th>Application</th><th>Include requests</th><th>Disk opens</th><th>Source/token cache hits</th><th>Guard skips</th><th>Mapped files</th></tr></thead><tbody id="cache"></tbody></table></div>
<p class="note">Counters sum all 44 translation units; each call has its own fresh cache. Embedded headers account for some includes and require no disk open. Source-open counts exclude path-resolution metadata operations and top-level input loading. A cache hit reuses unexpanded tokens; it does not reuse a previous macro expansion.</p>
<p><strong>Mapping is a small secondary effect.</strong> Compared with cached reads, mapping files of at least 64 KiB reduces the aggregate paired time by <span id="mapping"></span>. Two of the three application intervals include no change. Small/empty files and unavailable mappings use reads; mapped UTF-8 is validated once per cached source.</p>
<h3>Allocation and memory checks</h3><div class="tablewrap"><table><thead><tr><th>Application</th><th>Allocator calls</th><th>Fewer calls</th><th>Requested bytes saved</th><th>Peak RSS, MiB</th></tr></thead><tbody id="memory"></tbody></table></div>
<p class="note">Previous → final. Counts come from identical allocator-instrumented harnesses, separate from latency timing. Requested bytes are cumulative allocation/reallocation requests, exclude mapped storage, and are not peak memory. Peak RSS is one full counting-process run per application/version, including warmups and raw input reading; it is not an isolated per-call memory measurement.</p>
<p><strong class="ok">Correctness verified.</strong> All five versions produce byte-identical preprocessed text on Lua, QuickJS and SQLite, and each output compiles to verified IR. Regressions cover repeated includes with changing macros, guard undefinition, path aliases, conditional <code>#pragma once</code>, search origins, physical diagnostics and malformed nested conditionals.</p>
<details><summary>Method, lifetime contract and reproduction</summary><ul><li>Lua 5.4.7 (33 files), QuickJS 2024-01-13 with BigNum (9), SQLite 3.46.1 and shell (2). All versions use identical raw sources, defines, SDK and include paths.</li><li>Measurements include header reads, scanning, expansion, output formatting and internal destruction. Top-level source reading, SDK discovery, process startup and returned-string destruction are outside timing. C-to-IR, optimization, codegen and linking are not measured here.</li><li>Applications shuffle each round; five immutable variants rotate execution order. Each process warms its entire application before timing. Bootstrap intervals resample same-round pairs within each fixed application; aggregate ratios weight the three application medians equally.</li><li>The arena/no-cache and cached-read ablations differ from the final implementation only in internal compile-time constants disabling the source/token/guard cache and memory mapping. Source hashes and exact patches are retained.</li><li>Included files must remain unchanged during a preprocessing call. Cached source/lexical snapshots and read-only COW maps live only for that call. Future calls reread current contents. COW does not protect against another process truncating a mapped file.</li><li>Profiling counters use a separate TRACK=true monomorphization. The ordinary API compiles the counters away, and preserves its existing signature.</li><li>57 C frontend tests and 7 driver integration tests pass. Formatting and diff checks pass. These warm-cache results are from Apple M5 Max; other CPUs and cold-storage behavior have not been measured.</li></ul></details>
<p class="foot">Saved under suite/reports/c-preprocessor-arena-20261015.html, with paired raw data, storage counters, build/source hashes, and exact ablation patches. Reproduction commands are in suite/README.md.</p>
<script>const D=__DATA__;const apps=['lua','quickjs','sqlite'];const labels={lua:'Lua',quickjs:'QuickJS',sqlite:'SQLite'};const variants=['baseline','arena','cache-read','cache-mmap'];const names=['Previous optimized','Arena, no cache','Cached reads','Cached maps'];const colors=['#939aa7','#4d9ed6','#d9a24d','#46aa93'];let relative=false;const fmt=n=>n.toFixed(1);function setRelative(x){relative=x;draw()}function draw(){document.getElementById('increment').textContent=D.aggregate.final_vs_previous.speedup.toFixed(2)+'×';document.getElementById('overall').textContent=D.aggregate.final_vs_original.speedup.toFixed(2)+'×';document.getElementById('mapping').textContent=((1-D.aggregate.mmap_vs_read.median_geomean_ratio)*100).toFixed(2)+'%';document.getElementById('absolute').classList.toggle('active',!relative);document.getElementById('relative').classList.toggle('active',relative);const max=relative?1:Math.max(...apps.map(a=>D.applications[a].median_ms.baseline));document.getElementById('bars').innerHTML=apps.map(a=>{const s=D.applications[a];return`<div class="bargroup"><b>${labels[a]}</b>${variants.map((v,i)=>{const t=s.median_ms[v],n=relative?t/s.median_ms.baseline:t;return`<div class="barline"><span>${names[i]}</span><div class="track"><div class="segment" style="width:${100*n/max}%;background:${colors[i]}" title="${labels[a]}: ${names[i]} ${fmt(t)} ms"></div></div><span>${relative?fmt(n*100)+'%':fmt(t)+' ms'}</span></div>`}).join('')}</div>`}).join('');document.getElementById('timing').innerHTML=apps.map(a=>{const s=D.applications[a],c=s.comparisons.final_vs_previous;return`<tr><td>${labels[a]}</td><td>${fmt(s.median_ms.original)}</td><td>${fmt(s.median_ms.baseline)}</td><td><strong>${fmt(s.median_ms['cache-mmap'])}</strong></td><td><strong>${c.speedup.toFixed(2)}×</strong></td><td>${(1/c.ratio_ci95[1]).toFixed(2)}–${(1/c.ratio_ci95[0]).toFixed(2)}×</td><td>${s.comparisons.final_vs_original.speedup.toFixed(2)}×</td></tr>`}).join('');document.getElementById('cache').innerHTML=apps.map(a=>{const s=D.applications[a].storage.cache_stats.totals;return`<tr><td>${labels[a]}</td><td>${s.include_requests.toLocaleString()}</td><td>${s.file_opens.toLocaleString()}</td><td>${s.source_cache_hits.toLocaleString()}</td><td>${s.guard_skips.toLocaleString()}</td><td>${s.mapped_files}</td></tr>`}).join('');document.getElementById('memory').innerHTML=apps.map(a=>{const s=D.applications[a].storage,b=s.baseline,c=s.candidate;return`<tr><td>${labels[a]}</td><td>${((b.totals.alloc+b.totals.realloc)/1e6).toFixed(2)}M → ${((c.totals.alloc+c.totals.realloc)/1e6).toFixed(2)}M</td><td><strong>${fmt(s.allocation_call_reduction*100)}%</strong></td><td>${fmt(s.requested_bytes_reduction*100)}%</td><td>${fmt(b.peak_rss_bytes/2**20)} → ${fmt(c.peak_rss_bytes/2**20)}</td></tr>`}).join('')}draw();console.log('Rendered paired arena/cache data, independent storage counters and memory measurements');</script></body></html>'''
html = html.replace('__STYLE__', style).replace('__DATA__', json.dumps(data, separators=(',', ':')))
output = directory / 'c-preprocessor-arena-20261015.html'
output.write_text(html)
print(output)
